// Contract for the NYC taxi trips dashboard mock module.
//
// export type Borough = "Manhattan" | "Brooklyn" | "Queens" | "Bronx" | "Staten Island";
// export type BoroughFilter = "all" | Borough;
// export type DateRangeOption = { id: "7d" | "14d" | "30d"; label: string; days: number };
// export type Kpi = { id: "trips" | "avgFare" | "tipRate"; label: string; value: string; delta: number; unit: string };
// export type DailyMetric = { date: string; label: string; borough: Borough; trips: number; avgFare: number; tipRate: number };
// export type DailyTotal = { date: string; label: string; trips: number; avgFare: number; tipRate: number };
// export type BoroughSummary = { borough: Borough; trips: number; avgFare: number; tipRate: number };
// export type HourlyTrips = { hour: string; trips: number };
// export type Trip = { id: string; pickupTime: string; pickupBorough: Borough; dropoffBorough: Borough; distanceMi: number; fare: number; tip: number; passengers: number; payment: "Card" | "Cash" };
// export type PaymentMix = { method: string; trips: number };
//
// export const boroughs: Borough[]
// export const dateRangeOptions: DateRangeOption[]
// export const kpis: Kpi[]
// export const dailyMetrics: DailyMetric[]
// export const dailyTotals: DailyTotal[]
// export const boroughSummary: BoroughSummary[]
// export const hourlyTrips: HourlyTrips[]
// export const paymentMix: PaymentMix[]
// export const recentTrips: Trip[]
// @end-contract

export type Borough =
  | "Manhattan"
  | "Brooklyn"
  | "Queens"
  | "Bronx"
  | "Staten Island";
export type BoroughFilter = "all" | Borough;
export type DateRangeOption = {
  id: "7d" | "14d" | "30d";
  label: string;
  days: number;
};
export type Kpi = {
  id: "trips" | "avgFare" | "tipRate";
  label: string;
  value: string;
  delta: number;
  unit: string;
};
export type DailyMetric = {
  date: string;
  label: string;
  borough: Borough;
  trips: number;
  avgFare: number;
  tipRate: number;
};
export type DailyTotal = {
  date: string;
  label: string;
  trips: number;
  avgFare: number;
  tipRate: number;
};
export type BoroughSummary = {
  borough: Borough;
  trips: number;
  avgFare: number;
  tipRate: number;
};
export type HourlyTrips = { hour: string; trips: number };
export type Trip = {
  id: string;
  pickupTime: string;
  pickupBorough: Borough;
  dropoffBorough: Borough;
  distanceMi: number;
  fare: number;
  tip: number;
  passengers: number;
  payment: "Card" | "Cash";
};
export type PaymentMix = { method: string; trips: number };

export const boroughs: Borough[] = [
  "Manhattan",
  "Brooklyn",
  "Queens",
  "Bronx",
  "Staten Island",
];

export const dateRangeOptions: DateRangeOption[] = [
  { id: "7d", label: "Last 7 days", days: 7 },
  { id: "14d", label: "Last 14 days", days: 14 },
  { id: "30d", label: "Last 30 days", days: 30 },
];

const share: Record<Borough, number> = {
  Manhattan: 0.62,
  Brooklyn: 0.14,
  Queens: 0.18,
  Bronx: 0.05,
  "Staten Island": 0.01,
};
const fareBase: Record<Borough, number> = {
  Manhattan: 17.8,
  Brooklyn: 22.4,
  Queens: 38.5,
  Bronx: 26.1,
  "Staten Island": 41.2,
};
const tipBase: Record<Borough, number> = {
  Manhattan: 21.5,
  Brooklyn: 18.2,
  Queens: 17.4,
  Bronx: 14.6,
  "Staten Island": 13.1,
};

const monthNames = [
  "Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec",
];

function buildDays(count: number): { date: string; label: string; dow: number }[] {
  const out: { date: string; label: string; dow: number }[] = [];
  const start = Date.UTC(2024, 4, 5); // 2024-05-05
  for (let i = 0; i < count; i++) {
    const d = new Date(start + i * 86400000);
    const iso = d.toISOString().slice(0, 10);
    out.push({
      date: iso,
      label: `${monthNames[d.getUTCMonth()]} ${d.getUTCDate()}`,
      dow: d.getUTCDay(),
    });
  }
  return out;
}

const days = buildDays(30);
const dowFactor = [0.82, 0.9, 0.96, 1.0, 1.05, 1.18, 1.12];

export const dailyMetrics: DailyMetric[] = days.flatMap((d, i) =>
  boroughs.map((b, j) => {
    const wiggle = Math.sin(i * 1.3 + j) * 0.04;
    return {
      date: d.date,
      label: d.label,
      borough: b,
      trips: Math.round(
        98000 * share[b] * (dowFactor[d.dow] ?? 1) * (1 + wiggle + i * 0.002),
      ),
      avgFare: Math.round((fareBase[b] + Math.cos(i + j) * 0.9) * 100) / 100,
      tipRate: Math.round((tipBase[b] + Math.sin(i * 0.7 + j) * 1.2) * 10) / 10,
    };
  }),
);

export const dailyTotals: DailyTotal[] = days.map((d) => {
  const rows = dailyMetrics.filter((m) => m.date === d.date);
  const trips = rows.reduce((s, r) => s + r.trips, 0);
  const avgFare =
    rows.reduce((s, r) => s + r.avgFare * r.trips, 0) / trips;
  const tipRate =
    rows.reduce((s, r) => s + r.tipRate * r.trips, 0) / trips;
  return {
    date: d.date,
    label: d.label,
    trips,
    avgFare: Math.round(avgFare * 100) / 100,
    tipRate: Math.round(tipRate * 10) / 10,
  };
});

export const kpis: Kpi[] = [
  { id: "trips", label: "Trips / day", value: "101,840", delta: 4.2, unit: "trips" },
  { id: "avgFare", label: "Avg fare", value: "$22.35", delta: 1.8, unit: "USD" },
  { id: "tipRate", label: "Tip rate", value: "19.7%", delta: -0.6, unit: "%" },
];

export const boroughSummary: BoroughSummary[] = boroughs.map((b) => {
  const rows = dailyMetrics.filter((m) => m.borough === b);
  const trips = rows.reduce((s, r) => s + r.trips, 0);
  return {
    borough: b,
    trips,
    avgFare:
      Math.round((rows.reduce((s, r) => s + r.avgFare, 0) / rows.length) * 100) / 100,
    tipRate:
      Math.round((rows.reduce((s, r) => s + r.tipRate, 0) / rows.length) * 10) / 10,
  };
});

export const hourlyTrips: HourlyTrips[] = Array.from({ length: 24 }, (_, h) => {
  const curve =
    2200 +
    5200 * Math.exp(-Math.pow(h - 8.5, 2) / 6) +
    7400 * Math.exp(-Math.pow(h - 18.5, 2) / 9) -
    1800 * Math.exp(-Math.pow(h - 4, 2) / 4);
  return { hour: `${String(h).padStart(2, "0")}:00`, trips: Math.round(curve) };
});

export const paymentMix: PaymentMix[] = [
  { method: "Credit card", trips: 71200 },
  { method: "Cash", trips: 24100 },
  { method: "Other", trips: 6540 },
];

export const recentTrips: Trip[] = [
  { id: "T-48213", pickupTime: "2024-06-03T08:14:00", pickupBorough: "Manhattan", dropoffBorough: "Manhattan", distanceMi: 2.4, fare: 14.5, tip: 3.2, passengers: 1, payment: "Card" },
  { id: "T-48214", pickupTime: "2024-06-03T08:17:00", pickupBorough: "Queens", dropoffBorough: "Manhattan", distanceMi: 9.8, fare: 41.0, tip: 8.0, passengers: 2, payment: "Card" },
  { id: "T-48215", pickupTime: "2024-06-03T08:22:00", pickupBorough: "Brooklyn", dropoffBorough: "Brooklyn", distanceMi: 3.1, fare: 17.8, tip: 0, passengers: 1, payment: "Cash" },
  { id: "T-48216", pickupTime: "2024-06-03T08:31:00", pickupBorough: "Manhattan", dropoffBorough: "Queens", distanceMi: 17.2, fare: 68.5, tip: 12.0, passengers: 3, payment: "Card" },
  { id: "T-48217", pickupTime: "2024-06-03T08:36:00", pickupBorough: "Bronx", dropoffBorough: "Manhattan", distanceMi: 6.7, fare: 29.3, tip: 5.0, passengers: 1, payment: "Card" },
  { id: "T-48218", pickupTime: "2024-06-03T08:44:00", pickupBorough: "Manhattan", dropoffBorough: "Brooklyn", distanceMi: 5.2, fare: 24.0, tip: 4.8, passengers: 1, payment: "Card" },
  { id: "T-48219", pickupTime: "2024-06-03T08:52:00", pickupBorough: "Staten Island", dropoffBorough: "Brooklyn", distanceMi: 8.9, fare: 38.7, tip: 0, passengers: 2, payment: "Cash" },
  { id: "T-48220", pickupTime: "2024-06-03T08:58:00", pickupBorough: "Manhattan", dropoffBorough: "Manhattan", distanceMi: 1.3, fare: 9.8, tip: 2.0, passengers: 1, payment: "Card" },
];

