import {
  Badge,
  BarChart,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  DonutChart,
  LineChart,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  ToggleGroup,
  ToggleGroupItem,
} from "@databricks/appkit-ui/react";
import { Car, DollarSign, Download, Percent } from "lucide-react";
import { useMemo, useState } from "react";

import {
  boroughs,
  dailyMetrics,
  dateRangeOptions,
  hourlyTrips,
  kpis,
  paymentMix,
  recentTrips,
} from "../mock";
import type { BoroughFilter } from "../mock";

const icons = { trips: Car, avgFare: DollarSign, tipRate: Percent };

export default function TaxiDashboard() {
  const [range, setRange] = useState<string>(dateRangeOptions[0].id);
  const [borough, setBorough] = useState<BoroughFilter>("all");

  const days =
    dateRangeOptions.find((o) => o.id === range)?.days ??
    dateRangeOptions[0].days;

  const daily = useMemo(() => {
    const dates = Array.from(new Set(dailyMetrics.map((d) => d.date)))
      .sort()
      .slice(-days);
    return dates.map((date) => {
      const rows = dailyMetrics.filter(
        (d) => d.date === date && (borough === "all" || d.borough === borough),
      );
      const trips = rows.reduce((s, r) => s + r.trips, 0);
      const avgFare = trips
        ? rows.reduce((s, r) => s + r.avgFare * r.trips, 0) / trips
        : 0;
      const tipRate = trips
        ? rows.reduce((s, r) => s + r.tipRate * r.trips, 0) / trips
        : 0;
      return {
        date,
        label: rows[0]?.label ?? date,
        trips,
        avgFare: Math.round(avgFare * 100) / 100,
        tipRate: Math.round(tipRate * 10) / 10,
      };
    });
  }, [days, borough]);

  const byBorough = useMemo(() => {
    const dates = new Set(daily.map((d) => d.date));
    return boroughs.map((b) => {
      const rows = dailyMetrics.filter(
        (d) => d.borough === b && dates.has(d.date),
      );
      const trips = rows.reduce((s, r) => s + r.trips, 0);
      const avgFare = trips
        ? rows.reduce((s, r) => s + r.avgFare * r.trips, 0) / trips
        : 0;
      const tipRate = trips
        ? rows.reduce((s, r) => s + r.tipRate * r.trips, 0) / trips
        : 0;
      return { borough: b, trips, avgFare, tipRate };
    });
  }, [daily]);

  const trips = recentTrips.filter(
    (t) => borough === "all" || t.pickupBorough === borough,
  );

  return (
    <div className="mx-auto max-w-7xl space-y-4 p-6">
      <header className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">
            NYC taxi trips
          </h1>
          <p className="text-sm text-muted-foreground">
            Operations overview ·{" "}
            {borough === "all" ? "All boroughs" : borough}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <ToggleGroup
            type="single"
            value={range}
            onValueChange={(v) => v && setRange(v)}
          >
            {dateRangeOptions.map((o) => (
              <ToggleGroupItem key={o.id} value={o.id}>
                {o.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <Select
            value={borough}
            onValueChange={(v) => setBorough(v as BoroughFilter)}
          >
            <SelectTrigger className="w-44">
              <SelectValue placeholder="Borough" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All boroughs</SelectItem>
              {boroughs.map((b) => (
                <SelectItem key={b} value={b}>
                  {b}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button variant="outline" size="sm">
            <Download /> Export
          </Button>
        </div>
      </header>

      <div className="grid gap-4 sm:grid-cols-3">
        {kpis.map((k) => {
          const Icon = icons[k.id];
          return (
            <Card key={k.id}>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardDescription>{k.label}</CardDescription>
                <Icon className="size-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-3xl font-semibold tabular-nums">
                  {k.value}
                  <span className="ml-1 text-sm font-normal text-muted-foreground">
                    {k.unit}
                  </span>
                </div>
                <p
                  className={
                    k.delta >= 0
                      ? "text-xs text-success"
                      : "text-xs text-destructive"
                  }
                >
                  {k.delta >= 0 ? "+" : ""}
                  {k.delta}% vs prior period
                </p>
              </CardContent>
            </Card>
          );
        })}
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>Trips per day</CardTitle>
          </CardHeader>
          <CardContent>
            <LineChart data={daily} xKey="date" yKey="trips" height={240} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Payment mix</CardTitle>
          </CardHeader>
          <CardContent>
            <DonutChart
              data={paymentMix}
              xKey="method"
              yKey="trips"
              height={240}
            />
          </CardContent>
        </Card>
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card>
          <CardHeader>
            <CardTitle>Average fare ($)</CardTitle>
          </CardHeader>
          <CardContent>
            <LineChart data={daily} xKey="date" yKey="avgFare" height={200} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Tip rate (%)</CardTitle>
          </CardHeader>
          <CardContent>
            <LineChart data={daily} xKey="date" yKey="tipRate" height={200} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Trips by hour</CardTitle>
          </CardHeader>
          <CardContent>
            <BarChart
              data={hourlyTrips}
              xKey="hour"
              yKey="trips"
              height={200}
            />
          </CardContent>
        </Card>
      </div>

      <div className="grid gap-4 lg:grid-cols-5">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>Boroughs</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Borough</TableHead>
                  <TableHead className="text-right">Trips</TableHead>
                  <TableHead className="text-right">Fare</TableHead>
                  <TableHead className="text-right">Tip</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {byBorough.map((b) => (
                  <TableRow
                    key={b.borough}
                    className="cursor-pointer"
                    onClick={() => setBorough(b.borough)}
                  >
                    <TableCell className="font-medium">{b.borough}</TableCell>
                    <TableCell className="text-right tabular-nums">
                      {b.trips.toLocaleString()}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">
                      ${b.avgFare.toFixed(2)}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">
                      {b.tipRate.toFixed(1)}%
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
        <Card className="lg:col-span-3">
          <CardHeader>
            <CardTitle>Recent trips</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Pickup</TableHead>
                  <TableHead>Route</TableHead>
                  <TableHead className="text-right">Miles</TableHead>
                  <TableHead className="text-right">Fare</TableHead>
                  <TableHead className="text-right">Tip</TableHead>
                  <TableHead>Pay</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {trips.map((t) => (
                  <TableRow key={t.id}>
                    <TableCell className="text-muted-foreground">
                      {t.pickupTime}
                    </TableCell>
                    <TableCell>
                      {t.pickupBorough} → {t.dropoffBorough}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">
                      {t.distanceMi.toFixed(1)}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">
                      ${t.fare.toFixed(2)}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">
                      ${t.tip.toFixed(2)}
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant={t.payment === "Card" ? "secondary" : "outline"}
                      >
                        {t.payment}
                      </Badge>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

