import {
  Badge,
  BarChart,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  AreaChart,
  DonutChart,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  ToggleGroup,
  ToggleGroupItem,
} from "@databricks/appkit-ui/react";
import { Car, DollarSign, Percent, TrendingDown, TrendingUp } from "lucide-react";
import { useMemo, useState } from "react";

import {
  boroughs,
  dailyMetrics,
  dateRangeOptions,
  hourlyTrips,
  kpis,
  paymentMix,
  recentTrips,
} from "../mock";
import type { BoroughFilter } from "../mock";

const icons = { trips: Car, avgFare: DollarSign, tipRate: Percent };

export default function TaxiDashboard() {
  const [range, setRange] = useState<string>("14d");
  const [borough, setBorough] = useState<BoroughFilter>("all");

  const days = dateRangeOptions.find((o) => o.id === range)?.days ?? 14;

  const daily = useMemo(() => {
    const dates = Array.from(new Set(dailyMetrics.map((d) => d.date)))
      .sort()
      .slice(-days);
    const set = new Set(dates);
    return dates.map((date) => {
      const rows = dailyMetrics.filter(
        (d) => d.date === date && set.has(d.date) && (borough === "all" || d.borough === borough),
      );
      const trips = rows.reduce((s, r) => s + r.trips, 0);
      const avgFare = trips ? rows.reduce((s, r) => s + r.avgFare * r.trips, 0) / trips : 0;
      const tipRate = trips ? rows.reduce((s, r) => s + r.tipRate * r.trips, 0) / trips : 0;
      return {
        date,
        label: rows[0]?.label ?? date,
        trips,
        avgFare: Math.round(avgFare * 100) / 100,
        tipRate: Math.round(tipRate * 10) / 10,
      };
    });
  }, [days, borough]);

  const byBorough = useMemo(() => {
    const dates = new Set(
      Array.from(new Set(dailyMetrics.map((d) => d.date))).sort().slice(-days),
    );
    return boroughs.map((b) => {
      const rows = dailyMetrics.filter((d) => d.borough === b && dates.has(d.date));
      return { borough: b, trips: rows.reduce((s, r) => s + r.trips, 0) };
    });
  }, [days]);

  const trips = recentTrips.filter(
    (t) => borough === "all" || t.pickupBorough === borough,
  );

  const hero = kpis.find((k) => k.id === "trips");
  const others = kpis.filter((k) => k.id !== "trips");
  const HeroIcon = Car;

  return (
    <div className="mx-auto max-w-6xl space-y-10 px-6 py-12">
      <header className="flex flex-wrap items-end justify-between gap-6">
        <div className="space-y-2">
          <Badge variant="secondary">Operations</Badge>
          <h1 className="text-4xl font-bold tracking-tight">NYC taxi trips</h1>
          <p className="text-muted-foreground">
            Demand, fares and tipping across the five boroughs.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <ToggleGroup
            type="single"
            value={range}
            onValueChange={(v) => v && setRange(v)}
          >
            {dateRangeOptions.map((o) => (
              <ToggleGroupItem key={o.id} value={o.id}>
                {o.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <Select value={borough} onValueChange={(v) => setBorough(v as BoroughFilter)}>
            <SelectTrigger className="w-44">
              <SelectValue placeholder="Borough" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All boroughs</SelectItem>
              {boroughs.map((b) => (
                <SelectItem key={b} value={b}>
                  {b}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </header>

      <section className="grid gap-6 lg:grid-cols-3">
        {hero && (
          <Card className="bg-primary text-primary-foreground lg:col-span-2">
            <CardHeader>
              <CardDescription className="flex items-center gap-2 text-primary-foreground/80">
                <HeroIcon className="size-4" /> {hero.label}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-2">
              <div className="text-7xl font-bold tabular-nums tracking-tight">
                {hero.value}
              </div>
              <p className="text-sm text-primary-foreground/80">
                {hero.delta >= 0 ? "+" : ""}
                {hero.delta}% vs previous period · {hero.unit}
              </p>
            </CardContent>
          </Card>
        )}
        <div className="grid gap-6">
          {others.map((k) => {
            const Icon = icons[k.id];
            const Trend = k.delta >= 0 ? TrendingUp : TrendingDown;
            return (
              <Card key={k.id}>
                <CardHeader className="flex flex-row items-center justify-between">
                  <CardDescription>{k.label}</CardDescription>
                  <Icon className="size-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-4xl font-semibold tabular-nums">{k.value}</div>
                  <p
                    className={`flex items-center gap-1 text-xs ${
                      k.delta >= 0 ? "text-success" : "text-destructive"
                    }`}
                  >
                    <Trend className="size-3" />
                    {k.delta >= 0 ? "+" : ""}
                    {k.delta}% · {k.unit}
                  </p>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </section>

      <Card>
        <CardHeader>
          <CardTitle className="text-xl">Trips per day</CardTitle>
          <CardDescription>
            {borough === "all" ? "All boroughs" : borough} · last {days} days
          </CardDescription>
        </CardHeader>
        <CardContent>
          <AreaChart data={daily} xKey="date" yKey="trips" height={340} smooth />
        </CardContent>
      </Card>

      <section className="grid gap-6 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Avg fare ($)</CardTitle>
          </CardHeader>
          <CardContent>
            <BarChart data={daily} xKey="label" yKey="avgFare" height={240} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Tip rate (%)</CardTitle>
          </CardHeader>
          <CardContent>
            <AreaChart data={daily} xKey="date" yKey="tipRate" height={240} smooth />
          </CardContent>
        </Card>
      </section>

      <section className="grid gap-6 md:grid-cols-3">
        <Card>
          <CardHeader>
            <CardTitle>Trips by borough</CardTitle>
          </CardHeader>
          <CardContent>
            <BarChart
              data={byBorough}
              xKey="borough"
              yKey="trips"
              orientation="horizontal"
              height={240}
            />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Trips by hour</CardTitle>
          </CardHeader>
          <CardContent>
            <BarChart data={hourlyTrips} xKey="hour" yKey="trips" height={240} />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Payment mix</CardTitle>
          </CardHeader>
          <CardContent>
            <DonutChart data={paymentMix} xKey="method" yKey="trips" height={240} />
          </CardContent>
        </Card>
      </section>

      <Card>
        <CardHeader>
          <CardTitle>Recent trips</CardTitle>
          <CardDescription>Filtered by pickup borough</CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Pickup</TableHead>
                <TableHead>Route</TableHead>
                <TableHead className="text-right">Miles</TableHead>
                <TableHead className="text-right">Fare</TableHead>
                <TableHead className="text-right">Tip</TableHead>
                <TableHead>Payment</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {trips.map((t) => (
                <TableRow key={t.id}>
                  <TableCell className="text-muted-foreground">{t.pickupTime}</TableCell>
                  <TableCell className="font-medium">
                    {t.pickupBorough} → {t.dropoffBorough}
                  </TableCell>
                  <TableCell className="text-right tabular-nums">{t.distanceMi.toFixed(1)}</TableCell>
                  <TableCell className="text-right tabular-nums">${t.fare.toFixed(2)}</TableCell>
                  <TableCell className="text-right tabular-nums">${t.tip.toFixed(2)}</TableCell>
                  <TableCell>
                    <Badge variant={t.payment === "Card" ? "default" : "outline"}>
                      {t.payment}
                    </Badge>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}
